const compact=v=>v==null?'—':Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(v),metric=(label,value)=>{const el=document.createElement('div');el.className='metric';const l=document.createElement('span');l.className='metric-label';l.textContent=label;const v=document.createElement('strong');v.textContent=value;el.append(l,v);return el;};
document.getElementById('year').textContent=new Date().getFullYear();
async function refresh(){try{const response=await fetch('data/test-token.json',{cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json(),t=data.token;document.getElementById('test-updated').textContent=`Snapshot: ${new Date(data.generatedAt).toLocaleString()} · ICP ledger ${data.config.ledgerCanisterId} · market ${data.config.marketCanisterId}`;document.getElementById('test-metrics').replaceChildren(metric('Network','ICP'),metric('Token',data.config.symbol),metric('Holders',compact(t.holders)),metric('Index status',t.holdersStatus));document.querySelectorAll('[data-link=explorer]').forEach(button=>button.onclick=()=>open(data.config.links.explorer,'_blank','noopener'));document.querySelectorAll('[data-link=buy]').forEach(button=>button.onclick=()=>open(data.config.links.buy,'_blank','noopener'));}catch{document.getElementById('test-updated').textContent='ICP test snapshot unavailable.';}}
refresh();
